'AC11.2.2'; from datetime import date; from decimal import Decimal; from unittest.mock import patch; from src.extraction.orm.layer3 import ManagedPosition, PositionStatus; from src.portfolio import PositionServiceError
class TestAssetsRouterCoverage:
    async def test_get_depreciation_asset_service_error(self, client, db, test_user):
        from src.ledger import Account, AccountType; account = Account(user_id=test_user.id, name='Real Estate', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='BUILDING', quantity=Decimal('1'), cost_basis=Decimal('500000.00'), status=PositionStatus.ACTIVE, acquisition_date=date(2020, 1, 1), currency='USD'); db.add(position); await db.commit(); await db.refresh(position)
        with patch('src.routers.assets._positions.get_depreciation_schedule') as mock_depreciation: mock_depreciation.side_effect = PositionServiceError('Invalid asset for depreciation'); response = await client.get(f'/assets/positions/{position.id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 10}); assert response.status_code == 400; assert 'Invalid asset for depreciation' in response.json()['detail']
    async def test_get_depreciation_success(self, client, db, test_user):
        from src.ledger import Account, AccountType; from src.portfolio import DepreciationResult; account = Account(user_id=test_user.id, name='Fixed Assets', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='EQUIPMENT', quantity=Decimal('1'), cost_basis=Decimal('10000.00'), status=PositionStatus.ACTIVE, acquisition_date=date(2023, 1, 1), currency='USD'); db.add(position); await db.commit(); await db.refresh(position); mock_result = DepreciationResult(position_id=position.id, asset_identifier='EQUIPMENT', period_depreciation=Decimal('2000.00'), accumulated_depreciation=Decimal('2000.00'), book_value=Decimal('8000.00'), method='straight-line', useful_life_years=5, salvage_value=Decimal('0'))
        with patch('src.routers.assets._positions.get_depreciation_schedule') as mock_depreciation: mock_depreciation.return_value = mock_result; response = await client.get(f'/assets/positions/{position.id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 5}); assert response.status_code == 200; data = response.json(); assert data['position_id'] == str(position.id); assert data['asset_identifier'] == 'EQUIPMENT'; assert data['method'] == 'straight-line'; assert data['useful_life_years'] == 5
